WITH with_latest AS (SELECT s.*, x.hire_date, x.job_title FROM departments s JOIN LATERAL (SELECT c.hire_date, c.job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN budget >= 4271000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, MAX(budget) AS max_budget, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, COUNT(*) FILTER (WHERE dept_name = 'Marketing') AS marketing_rows, PERCENTILE_APPROX(budget, 0.95) AS budget_p95 FROM with_latest GROUP BY CASE WHEN budget >= 4271000 THEN 'HIGH' ELSE 'LOW' END HAVING max_budget < 1000000 ORDER BY budget_tier
